import { db, ui, persist, rerender, navigate, esc, money, num, pct, icon, formatDate, timeLabel, relative, teamTypes, teamUsers, teamAccounts, modal, closeModal, toast, validateUserIdentity } from './core.js';
import { renderSyncHelp, bindSyncHelp } from './sync-help.js';

const sourceNames = {meta: 'Meta · Ad Accounts', rollup: 'Analytics · Roll Up Report'};
const roleNames = {admin:'Администратор', lead:'Тимлид', buyer:'Байер'};
const statusNames = {active:'Активен', invited:'Приглашён', disabled:'Отключён', revoked:'Отозван'};
const defaults = {metaInterval:15,rollupInterval:30,rpm:30,concurrency:2,retries:3,retryDelay:10,backoff:'exponential',timeout:30,staleAfter:60,paused:false};
let settingsTab = 'types';
let showArchived = false;
const uid = p => `${p}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,6)}`;
const admin = () => db.role === 'admin';
const teamName = () => db.teamProfiles?.[db.teamId]?.name || (db.teamId === 'alpha' ? 'Команда Alpha' : 'Команда Beta');
const dt = t => t ? new Date(t).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'}) + ' GMT+3' : 'Ещё не было';
const ago = t => {if(!t)return 'Нет успешной загрузки'; const min=Math.max(0,Math.floor((Date.now()-t)/60000)); return min<1?'меньше минуты назад':min<60?`${min} мин назад`:`${Math.floor(min/60)} ч ${min%60} мин назад`;};
const safeIcon = name => icon(({refresh:'sync',layers:'box',lock:'shield','chevron-right':'chevron','arrow-right':'arrow',activity:'chart',alert:'warning'})[name] || name);
document.addEventListener('click',e=>{if(e.target.closest('[data-modal-close]'))closeModal();});
function ensureSync(){
  db.sync ||= {};
  db.sync.config = {...defaults,...db.sync.config};
  const now=Date.now();
  for(const k of ['meta','rollup']) db.sync[k] ||= {lastSuccess:now-(k==='meta'?4:12)*60000,lastAttempt:now-(k==='meta'?4:12)*60000,status:'fresh',next:now+(k==='meta'?11:18)*60000};
  db.sync.logs ||= [];
}
function addLog(source,status,message,extra={}){db.sync.logs.unshift({id:uid('log'),source,time:Date.now(),status,requests:0,duration:'—',message,...extra}); db.sync.logs=db.sync.logs.slice(0,40);}
function effectiveStatus(key){ensureSync();const s=db.sync[key]; if(s.status==='running') return 'running';if(db.sync.config.paused) return 'paused';if(s.status==='error')return 'error';if(!s.lastSuccess || Date.now()-s.lastSuccess>db.sync.config.staleAfter*60000)return 'stale';return 'fresh';}
const syncLabels={fresh:'Актуальные данные',stale:'Данные устарели',error:'Ошибка синхронизации',running:'Обновление',paused:'На паузе'};
function syncBadge(status){return `<span class="badge badge-${{fresh:'green',stale:'amber',error:'red',running:'blue',paused:'gray'}[status]||'gray'}"><span class="status-dot ${status==='running'?'pulse':''}"></span>${syncLabels[status]||esc(status)}</span>`;}
function typeCount(id){return teamAccounts().filter(a=>a.typeId===id).length;}
function initials(name){return String(name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function invitedUrl(u){return `${location.origin}${location.pathname}#invite/${u.id}/${u.token}`;}
function issueInvitation(u){u.status='invited';u.token=uid('invite');u.invitedAt=Date.now();u.expires=Date.now()+7*86400000;}
const durationLabel = v => typeof v==='number' ? `${v} сек` : v || '—';
function pageHead(title,subtitle,action=''){return `<div class="page-header"><div><div class="eyebrow">РАБОЧЕЕ ПРОСТРАНСТВО</div><h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${action}</div></div>`;}

export function renderSettings(tab){
  settingsTab = tab || ui.settingsTab || settingsTab;
  ui.settingsTab = settingsTab;
  const action=`<button class="btn" data-profile>${safeIcon('user')} Мой профиль</button>`+(settingsTab==='types'?`<button class="btn btn-primary" id="new-type">${safeIcon('plus')} Добавить тип</button>`:settingsTab==='users'&&admin()?`<button class="btn btn-primary" id="invite-user">${safeIcon('plus')} Пригласить участника</button>`:'');
  return `${pageHead('Настройки команды','Общие справочники и участники вашего пространства.',action)}
  <div class="tabs settings-tabs" role="tablist" aria-label="Настройки команды">${[['types','Типы кабинетов'],['users','Участники'],['general','Общие']].map(([k,l])=>`<button class="tab ${settingsTab===k?'active':''}" role="tab" aria-selected="${settingsTab===k}" data-settings-tab="${k}">${l}${k==='types'?` <span class="tab-count">${teamTypes().length}</span>`:k==='users'?` <span class="tab-count">${teamUsers().length}</span>`:''}</button>`).join('')}</div>
  ${settingsTab==='types'?renderTypes():settingsTab==='users'?renderUsers():renderGeneral()}`;
}
function renderTypes(){const types=teamTypes(true).filter(t=>showArchived?!!t.archived:!t.archived);return `
  <div class="panel">
    <div class="panel-head settings-types-head"><div><h2>Типы и цены</h2><p class="muted">Единый справочник для всех участников команды</p></div><div class="settings-type-filters"><label class="settings-search">${safeIcon('search')}<input id="type-search" placeholder="Найти тип…" aria-label="Найти тип"></label><select id="types-archive-filter" aria-label="Состояние типов"><option value="active" ${!showArchived?'selected':''}>Активные типы</option><option value="archived" ${showArchived?'selected':''}>Архив</option></select></div></div>
    <div class="table-wrap"><table class="data-table settings-table"><thead><tr><th>Название типа</th><th>Цена по умолчанию</th><th>Кабинетов</th><th>Состояние</th><th></th></tr></thead><tbody>${types.map((t,i)=>`<tr data-type-row="${esc(t.name.toLowerCase())}"><td><div class="type-cell"><span class="type-swatch" style="--swatch:${esc(t.color||'#737373')}">${safeIcon('layers')}</span><div><strong>${esc(t.name)}</strong><small>Тип ${String(i+1).padStart(2,'0')}</small></div></div></td><td class="mono">${money(t.price,2)}<span class="muted small"> / кабинет</span></td><td>${num(typeCount(t.id))}</td><td><span class="badge ${t.archived?'badge-gray':'badge-green'}">${t.archived?'В архиве':'Активен'}</span></td><td class="table-actions"><button class="btn btn-sm btn-ghost" data-edit-type="${t.id}" aria-label="Изменить ${esc(t.name)}">${safeIcon('edit')}<span>Изменить</span></button><button class="btn btn-sm btn-ghost" data-archive-type="${t.id}" aria-label="${t.archived?'Восстановить':'Архивировать'} ${esc(t.name)}">${safeIcon(t.archived?'unarchive':'archive')}</button></td></tr>`).join('') || `<tr><td colspan="5"><div class="empty"><strong>${showArchived?'Архив пуст':'Пока нет типов'}</strong><p>${showArchived?'Архивированные типы появятся здесь.':'Создайте первый тип для добавления кабинетов.'}</p></div></td></tr>`}</tbody></table></div>
  </div>
  <div id="type-search-empty" class="empty" hidden>Типы не найдены</div>`;}
function typeDialog(id){const t=id?db.types.find(t=>t.id===id&&t.team===db.teamId):null;if(id&&!t)return;
  modal(t?'Изменить тип кабинета':'Новый тип кабинета',`<form id="type-form" class="stack"><label class="field">Название<input name="name" required maxlength="70" placeholder="Например, Agency Premium" value="${esc(t?.name||'')}"></label><div class="form-grid"><label class="field">Цена за один кабинет, USD<input name="price" type="number" min="0" max="100000" step="0.01" required value="${t?.price??25}"></label><label class="field">Цвет<select name="color">${[['#7c6bea','Фиолетовый'],['#4b86dc','Синий'],['#44a989','Зелёный'],['#e3a653','Янтарный'],['#e27894','Розовый'],['#89909b','Серый']].map(([v,l])=>`<option value="${v}" ${t?.color===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="notice">${t?`Изменение цены не затронет ${typeCount(t.id)} существующих кабинетов этого типа, а применится только к новым кабинетам этого типа.`:'Тип будет доступен всем участникам вашей команды.'}</div><p id="type-form-error" class="form-error" hidden></p></form>`,`<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" type="submit" form="type-form">${t?'Сохранить изменения':'Создать тип'}</button>`);
  document.querySelector('#type-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name')).trim(),price=Number(f.get('price'));const err=document.querySelector('#type-form-error');if(!name||!Number.isFinite(price)||price<0){err.textContent='Укажите название и корректную цену.';err.hidden=false;return;}if(teamTypes(true).some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase())){err.textContent='Тип с таким названием уже есть в команде.';err.hidden=false;return;}if(t){t.name=name;t.price=price;t.color=f.get('color');t.updatedAt=Date.now();}else db.types.push({id:uid('type'),team:db.teamId,name,price,color:f.get('color'),archived:false});persist();closeModal();rerender();toast(t?'Тип обновлён. Стоимость старых кабинетов сохранена.':'Тип кабинета создан');});
}
function archiveDialog(id){const t=db.types.find(t=>t.id===id&&t.team===db.teamId);if(!t)return;if(t.archived){t.archived=false;persist();rerender();toast('Тип восстановлен');return;}modal('Архивировать тип?',`<p>Тип <strong>${esc(t.name)}</strong> перестанет появляться при добавлении новых кабинетов.</p><div class="notice">Все ${typeCount(id)} кабинетов и их статистика сохранятся. Тип можно восстановить из архива.</div>`,`<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="confirm-archive">Архивировать</button>`);document.querySelector('#confirm-archive').onclick=()=>{t.archived=true;persist();closeModal();rerender();toast('Тип перемещён в архив');};}
function renderUsers(){const users=teamUsers();return `<div class="panel"><div class="panel-head"><div><h2>Участники команды</h2><p class="muted">Все участники видят статистику команды</p></div><span class="badge badge-gray">${users.length} участников</span></div><div class="table-wrap"><table class="data-table settings-table"><thead><tr><th>Участник</th><th>Пользователь AIO</th><th>Роль</th><th>Состояние</th><th></th></tr></thead><tbody>${users.map((u,i)=>`<tr><td><div class="person-cell"><span class="person-avatar" style="--avatar-color:${['#e9e5fa','#e4eefc','#e2f0e9','#f7ebde'][i%4]}">${initials(u.username)}</span><div><strong>${esc(u.username)}${u.id===db.currentUserId?' <span class="muted small">Вы</span>':''}</strong><small>${esc(u.email)}</small></div></div></td><td><span class="mono small">${esc(u.aio||'Не привязан')}</span></td><td>${roleNames[u.role]||esc(u.role)}</td><td><span class="badge badge-${u.status==='active'?'green':u.status==='invited'?'blue':'gray'}">${u.status==='invited'&&u.expires&&u.expires<Date.now()?'Истекло':statusNames[u.status]||esc(u.status)}</span></td><td class="table-actions">${admin()?`<button class="btn btn-sm btn-ghost" data-user-manage="${u.id}">Настроить ${safeIcon('chevron-right')}</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="panel-foot muted">Приглашение создаёт ссылку. Отправьте её участнику удобным способом.</div></div><div class="info-strip">${safeIcon('lock')}<div><strong>Доступ ограничен вашей командой</strong><p>Типы, цены, кабинеты и результаты других команд недоступны.</p></div></div>`;}
function inviteDialog(){
  if(!admin())return;
  modal('Пригласить участника',`<form id="invite-form" class="stack"><label class="field">Username<input name="username" required maxlength="40" autocomplete="off" placeholder="ivan_buyer"><small>3–40 латинских букв, цифр, точек, тире или подчёркиваний.</small></label><label class="field">Email<input name="email" required type="email" autocomplete="email" placeholder="name@company.com"></label><div class="form-grid"><label class="field">Пользователь AIO<input name="aio" required placeholder="ivan_594"></label><label class="field">Роль<select name="role"><option value="buyer">Байер</option><option value="lead">Тимлид</option><option value="admin">Администратор</option></select></label></div><label class="field">Команда<input value="${esc(teamName())}" disabled></label><div class="notice">Участник задаст пароль при первом переходе. Ссылка действует 7 дней и используется один раз.</div><p id="invite-error" class="form-error" aria-live="polite" hidden></p></form>`,`<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" form="invite-form" type="submit">Создать приглашение</button>`);
  document.querySelector('#invite-form').onsubmit=e=>{
    e.preventDefault();if(!admin())return;
    const f=new FormData(e.currentTarget),email=String(f.get('email')||'').trim().toLowerCase(),username=String(f.get('username')||'').trim(),aio=String(f.get('aio')||'').trim(),role=String(f.get('role')||'');
    const error=validateUserIdentity(username,email)||(!aio?'Укажите пользователя AIO.':'')||(!Object.hasOwn(roleNames,role)?'Выберите роль участника.':'');
    if(error){const el=document.querySelector('#invite-error');el.textContent=error;el.hidden=false;return;}
    const user={id:uid('user'),team:db.teamId,email,username,aio,role};issueInvitation(user);db.users.push(user);persist();closeModal();rerender();invitationDialog(user);
  };
}
function invitationDialog(u){if(!u.token){u.token=uid('invite');persist();}modal(u.expires&&u.expires<Date.now()?'Приглашение истекло':'Приглашение готово',`<div class="invite-success">${safeIcon('check')}<h3>${esc(u.username)}</h3><p>${esc(u.email)} · ${roleNames[u.role]}</p></div><label class="field">Персональная ссылка<div class="copy-row"><input id="invite-link" class="mono" readonly value="${esc(invitedUrl(u))}"><button class="btn" id="copy-invite-link" aria-label="Копировать ссылку">${safeIcon('copy')}</button></div></label><div class="notice">Действует до ${dt(u.expires||Date.now()+7*86400000)}. Это демонстрационное приглашение.</div>`,`<button class="btn btn-ghost danger-text" id="revoke-invite">Отозвать</button><button class="btn" id="reissue-invite">Перевыпустить</button><button class="btn" id="preview-invite">Активация</button><button class="btn btn-primary" data-modal-close>Готово</button>`);document.querySelector('#copy-invite-link').onclick=async()=>{try{await navigator.clipboard.writeText(invitedUrl(u));toast('Ссылка скопирована');}catch{document.querySelector('#invite-link').select();toast('Выделили ссылку — скопируйте её');}};document.querySelector('#revoke-invite').onclick=()=>{u.status='revoked';u.expires=Date.now();persist();closeModal();rerender();toast('Приглашение отозвано');};document.querySelector('#reissue-invite').onclick=()=>{issueInvitation(u);persist();closeModal();rerender();invitationDialog(u);toast('Создана новая ссылка. Старая больше не действует.');};document.querySelector('#preview-invite').onclick=()=>{closeModal();navigate(`invite/${u.id}/${u.token}`);};}
function userDialog(id){
  if(!admin())return;const u=teamUsers().find(u=>u.id===id);if(!u)return;
  modal('Настройки участника',`<form id="user-form" class="stack"><div class="person-cell"><span class="person-avatar">${initials(u.username)}</span><div><strong>${esc(u.username)}</strong><small>${esc(u.email)}</small></div></div><label class="field">Username<input name="username" required maxlength="40" autocomplete="off" value="${esc(u.username)}"><small>3–40 латинских букв, цифр, точек, тире или подчёркиваний.</small></label><label class="field">Email<input name="email" required type="email" value="${esc(u.email)}"></label><label class="field">Пользователь AIO<input name="aio" value="${esc(u.aio||'')}" required></label><label class="field">Роль<select name="role" ${u.id===db.currentUserId?'disabled':''}>${Object.entries(roleNames).map(([r,n])=>`<option value="${r}" ${r===u.role?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Команда<input value="${esc(teamName())}" disabled></label>${u.id===db.currentUserId?'<p class="muted small">Свою роль нельзя изменить в этом окне.</p>':''}<div class="notice">Участник видит все кабинеты своей команды. Байер добавляет кабинеты только себе.</div><p id="user-form-error" class="form-error" aria-live="polite" hidden></p></form>`,`${u.status==='invited'?'<button class="btn" id="user-invitation">Приглашение</button>':`<button class="btn btn-ghost ${u.status==='active'?'danger-text':''}" id="toggle-user" ${u.id===db.currentUserId?'disabled':''}>${u.status==='active'?'Отключить доступ':u.status==='revoked'?'Выпустить приглашение':'Включить доступ'}</button>`}<button class="btn btn-primary" form="user-form" type="submit">Сохранить</button>`);
  document.querySelector('#user-form').onsubmit=e=>{
    e.preventDefault();if(!admin())return;
    const f=new FormData(e.currentTarget),username=String(f.get('username')||'').trim(),email=String(f.get('email')||'').trim().toLowerCase(),aio=String(f.get('aio')||'').trim(),role=u.id===db.currentUserId?u.role:String(f.get('role')||'');
    const error=validateUserIdentity(username,email,u.id)||(!aio?'Укажите пользователя AIO.':'')||(!Object.hasOwn(roleNames,role)?'Выберите роль участника.':'');
    if(error){const el=document.querySelector('#user-form-error');el.textContent=error;el.hidden=false;return;}
    Object.assign(u,{username,email,aio,role});persist();closeModal();rerender();toast('Участник обновлён');
  };
  document.querySelector('#user-invitation')?.addEventListener('click',()=>invitationDialog(u));
  document.querySelector('#toggle-user')?.addEventListener('click',()=>{
    if(!admin()||u.id===db.currentUserId)return;
    if(u.status==='revoked'){issueInvitation(u);persist();closeModal();rerender();invitationDialog(u);}
    else{u.status=u.status==='active'?'disabled':'active';persist();closeModal();rerender();toast(u.status==='active'?'Доступ включён':'Доступ отключён');}
  });
}
function renderGeneral(){return `<div class="settings-two-col"><div><h2>Рабочее пространство</h2><p class="muted">Название и базовые параметры команды.</p></div><div class="panel"><form id="team-form"><div class="panel-body stack"><label class="field">Название команды<input name="name" value="${esc(teamName())}" required maxlength="60" ${!admin()?'disabled':''}></label><div class="form-grid"><label class="field">Валюта отчётов<input value="USD · Доллар США" disabled></label><label class="field">Часовой пояс<input value="GMT+3" disabled></label></div><div class="notice">Данные AIO приводятся к единой валюте и часовому поясу. Все показатели — с даты выдачи кабинета.</div></div><div class="panel-foot"><span class="muted small">${admin()?'Изменения видны всем участникам команды':'Изменения доступны администратору'}</span>${admin()?'<button class="btn btn-primary" type="submit">Сохранить</button>':''}</div></form></div></div>`;}
export function bindSettings(){
  document.querySelectorAll('[data-settings-tab]').forEach(el=>el.onclick=()=>{ui.settingsTab=el.dataset.settingsTab;settingsTab=ui.settingsTab;rerender();});
  document.querySelector('#new-type')?.addEventListener('click',()=>typeDialog());
  document.querySelectorAll('[data-edit-type]').forEach(el=>el.onclick=()=>typeDialog(el.dataset.editType));
  document.querySelectorAll('[data-archive-type]').forEach(el=>el.onclick=()=>archiveDialog(el.dataset.archiveType));
  document.querySelector('#types-archive-filter')?.addEventListener('change',e=>{showArchived=e.target.value==='archived';rerender();});
  document.querySelector('#type-search')?.addEventListener('input',e=>{let visible=0;document.querySelectorAll('[data-type-row]').forEach(r=>{r.hidden=!r.dataset.typeRow.includes(e.target.value.toLowerCase());if(!r.hidden)visible++;});document.querySelector('#type-search-empty').hidden=visible>0||!e.target.value;});
  document.querySelector('#invite-user')?.addEventListener('click',inviteDialog);
  document.querySelectorAll('[data-user-manage]').forEach(el=>el.onclick=()=>userDialog(el.dataset.userManage));
  document.querySelector('#team-form')?.addEventListener('submit',e=>{e.preventDefault();if(!admin())return;const name=String(new FormData(e.currentTarget).get('name')).trim();if(!name)return;db.teamProfiles||={};db.teamProfiles[db.teamId]={...db.teamProfiles[db.teamId],name};persist();rerender();toast('Настройки команды сохранены');});
}

export function renderSync(){ensureSync();const cfg=db.sync.config;const anyRunning=['meta','rollup'].some(k=>effectiveStatus(k)==='running');const action=`${admin()?`<button class="btn" id="toggle-sync-pause">${safeIcon(cfg.paused?'play':'pause')} ${cfg.paused?'Возобновить':'Приостановить'}</button>`:''}<button class="btn btn-primary" id="sync-all" ${cfg.paused||anyRunning||!admin()?'disabled':''}>${safeIcon('refresh')} ${anyRunning?'Обновление…':'Обновить сейчас'}</button>`;
return `${pageHead('Синхронизация','Актуальность данных и управление нагрузкой на AIO.',action)}
<div class="sync-demo-bar"><div class="inline"><span class="badge badge-blue">Демо</span><span class="muted small">Посмотрите, как выглядит состояние источников</span></div><div class="segmented" role="group" aria-label="Сценарий синхронизации">${[['fresh','Всё в порядке'],['stale','Давно не обновлялось'],['error','Ошибка API']].map(([k,l])=>`<button class="${db.sync.demoScenario===k||(!db.sync.demoScenario&&k==='fresh')?'selected':''}" data-sync-scenario="${k}">${l}</button>`).join('')}</div></div>
${cfg.paused?'<div class="notice notice-amber sync-notice">Автоматическая синхронизация приостановлена. Последние успешно загруженные данные сохранены.</div>':''}
<div class="sync-sources">${['meta','rollup'].map(sourceCard).join('')}</div>
<div class="sync-workspace"><div class="panel sync-settings"><div class="panel-head"><div><h2>Параметры загрузки</h2><p class="muted">Общий лимит запросов к AIO, включая повторные попытки</p></div>${!admin()?'<span class="badge badge-gray">Только просмотр</span>':''}</div><form id="sync-config-form"><fieldset><div class="panel-body stack"><span class="section-label">Расписание</span><div class="form-grid">${numberField('Meta · каждые, мин','metaInterval',cfg.metaInterval,1,1440)}${numberField('Roll Up · каждые, мин','rollupInterval',cfg.rollupInterval,1,1440)}</div><div class="setting-divider"></div><span class="section-label">Нагрузка на API</span><div class="form-grid">${numberField('Запросов в минуту, максимум','rpm',cfg.rpm,1,300)}${numberField('Одновременных запросов','concurrency',cfg.concurrency,1,10)}</div><p class="muted small tight">Оба источника используют один лимит. Новый цикл не начинается, пока предыдущий не завершён.</p><div class="setting-divider"></div><span class="section-label">Повторные попытки</span><div class="form-grid">${numberField('Количество повторов','retries',cfg.retries,0,10)}${numberField('Начальная задержка, сек','retryDelay',cfg.retryDelay,1,300)}</div><div class="field"><div class="sync-field-heading"><label for="sync-backoff">Увеличение задержки</label>${renderSyncHelp('backoff','Увеличение задержки')}</div><select id="sync-backoff" name="backoff" ${!admin()?'disabled':''}><option value="exponential" ${cfg.backoff==='exponential'?'selected':''}>Экспоненциальное · ${cfg.retryDelay} → ${cfg.retryDelay*2} → ${cfg.retryDelay*4} сек</option><option value="fixed" ${cfg.backoff==='fixed'?'selected':''}>Фиксированная задержка</option></select></div><p class="muted small tight">При HTTP 429 учитывается Retry-After. Ошибки доступа 401/403 требуют проверки подключения.</p><div class="setting-divider"></div><div class="form-grid">${numberField('Таймаут запроса, сек','timeout',cfg.timeout,5,120)}${numberField('Считать устаревшими через, мин','staleAfter',cfg.staleAfter,5,1440)}</div><p id="sync-form-error" class="form-error" hidden></p><div id="sync-budget" class="sync-budget">${safeIcon('activity')}<span>Не более <strong>${cfg.rpm}</strong> запросов/мин · до <strong>${cfg.concurrency}</strong> одновременно</span></div></div></fieldset><div class="panel-foot"><span class="muted small">${admin()?'Настройки применяются к следующей загрузке':'Изменять параметры может администратор системы'}</span>${admin()?'<div class="inline"><button type="button" class="btn" id="reset-sync-config">Отменить</button><button class="btn btn-primary" type="submit">Сохранить</button></div>':''}</div></form></div>
<div class="sync-side"><div class="panel"><div class="panel-head"><h2>Как читается актуальность</h2></div><div class="panel-body stack sync-legend"><div><span class="status-dot fresh"></span><div><strong>Последняя успешная</strong><p>Когда данные действительно обновились. Не меняется после неудачной попытки.</p></div></div><div><span class="status-dot stale"></span><div><strong>Последняя попытка</strong><p>Когда система обращалась к AIO — независимо от результата.</p></div></div><div><span class="status-dot error"></span><div><strong>Ошибка не удаляет данные</strong><p>В отчётах остаются последние загруженные значения с заметной пометкой.</p></div></div></div></div><div class="panel"><div class="panel-body"><span class="app-logo-small">aıo</span><h3 class="mt-16">Один API, два источника</h3><p class="muted small">Raw Spend и статусы обновляются независимо от финансовых показателей Roll Up.</p><div class="source-detail"><span>Валюта</span><strong>USD</strong></div><div class="source-detail"><span>Часовой пояс</span><strong>GMT+3</strong></div><div class="source-detail"><span>Режим</span><span class="badge badge-blue">Моковые данные</span></div></div></div></div></div>
<div class="panel sync-log"><div class="panel-head"><div><h2>Журнал синхронизаций</h2><p class="muted">Последние попытки загрузки по двум источникам</p></div><select id="sync-log-filter" aria-label="Фильтр журнала"><option value="all">Все источники</option><option value="meta">Meta</option><option value="rollup">Roll Up</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Время · GMT+3</th><th>Источник</th><th>Результат</th><th>Запросов</th><th>Длительность</th><th></th></tr></thead><tbody>${db.sync.logs.map(log=>`<tr data-log-source="${esc(log.source)}"><td class="mono small">${dt(log.time).replace(' GMT+3','')}</td><td>${sourceNames[log.source]||esc(log.source)}</td><td><span class="badge badge-${log.status==='success'?'green':log.status==='error'?'red':'blue'}">${log.status==='success'?'Успешно':log.status==='error'?'Ошибка':'В процессе'}</span></td><td>${num(log.requests||0)}</td><td class="mono small">${esc(durationLabel(log.duration))}</td><td class="table-actions"><button class="btn btn-sm btn-ghost" data-sync-log="${log.id}">Подробнее ${safeIcon('chevron-right')}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Запустите синхронизацию, чтобы увидеть историю.</div></td></tr>'}</tbody></table></div><div class="panel-foot muted small">В прототипе загрузки имитируются. Запросы к API AIO не отправляются.</div></div>`;
}
function numberField(label,name,value,min,max){return `<div class="field"><div class="sync-field-heading"><label for="sync-${name}">${label}</label>${renderSyncHelp(name,label)}</div><input id="sync-${name}" name="${name}" type="number" min="${min}" max="${max}" step="1" required value="${value}" ${!admin()?'disabled':''}></div>`;}
function sourceCard(key){const s=db.sync[key],status=effectiveStatus(key);const meta=key==='meta';return `<section class="panel sync-source"><div class="panel-body"><div class="row-between"><div class="inline"><span class="source-icon ${meta?'meta-source':'rollup-source'}">${safeIcon(meta?'layers':'chart')}</span><div><h2>${meta?'Meta':'Roll Up Report'}</h2><p class="muted small">${meta?'Raw Spend · статус · причина Disabled':'Spend · Revenue · Profit'}</p></div></div></div><div class="sync-card-state">${syncBadge(status)}<span class="muted small">${ago(s.lastSuccess)}</span></div><dl class="sync-times"><div><dt class="sync-term">Последняя успешная ${renderSyncHelp('lastSuccess','Последняя успешная')}</dt><dd>${dt(s.lastSuccess)}</dd></div><div><dt class="sync-term">Последняя попытка ${renderSyncHelp('lastAttempt','Последняя попытка')}</dt><dd>${dt(s.lastAttempt)}</dd></div><div><dt>${status==='error'?'Следующая попытка':'Следующая загрузка'}</dt><dd>${status==='paused'?'На паузе':status==='running'?'После завершения текущей':dt(s.next)}</dd></div></dl>${status==='error'?`<div class="source-error">${safeIcon('alert')}<span>${esc(s.error||'HTTP 429 · превышен лимит запросов. Повтор через 60 сек.')}</span></div>`:status==='stale'?'<div class="source-warning">Данные старше установленного порога актуальности.</div>':status==='running'?'<div class="sync-progress"><span></span></div>':''}</div></section>`;}
export function runSync(){
  ensureSync();if(!admin()){toast('Запуск доступен администратору');return;}if(db.sync.config.paused){toast('Сначала возобновите синхронизацию');return;}
  if(['meta','rollup'].some(k=>db.sync[k].status==='running'))return;const sources=['meta','rollup'];const started=[];
  sources.forEach(k=>{if(!db.sync[k]||db.sync[k].status==='running')return;db.sync[k].status='running';db.sync[k].lastAttempt=Date.now();db.sync[k].error='';started.push(k);});
  if(!started.length)return;persist();rerender();
  setTimeout(()=>{started.forEach(k=>{const s=db.sync[k];if(!s)return;s.status='fresh';s.lastSuccess=Date.now();s.next=Date.now()+db.sync.config[k==='meta'?'metaInterval':'rollupInterval']*60000;s.error='';addLog(k,'success',k==='meta'?'Статусы и Raw Spend обновлены. Повторная загрузка обновляет существующие записи.':'Показатели кампаний обновлены. Связи с кабинетами сохранены.',{requests:k==='meta'?8:12,duration:k==='meta'?'1,4 сек':'2,1 сек'});});db.sync.demoScenario='fresh';persist();rerender();toast('Демонстрационные данные обновлены');},1500);
}
function applyScenario(scenario){ensureSync();const now=Date.now();db.sync.demoScenario=scenario;db.sync.config.paused=false;for(const key of ['meta','rollup']){const s=db.sync[key];s.status=scenario==='error'&&key==='rollup'?'error':'fresh';s.lastSuccess=now-(scenario==='stale'?125:key==='meta'?4:12)*60000;s.lastAttempt=scenario==='error'&&key==='rollup'?now:s.lastSuccess;s.next=now+(scenario==='error'&&key==='rollup'?1:key==='meta'?11:18)*60000;s.error=scenario==='error'&&key==='rollup'?'HTTP 429 · AIO ограничил запросы. Retry-After: 60 сек.':'';}if(scenario==='error')addLog('rollup','error','HTTP 429 Too Many Requests. Сервер передал Retry-After: 60 сек. Данные последней успешной загрузки сохранены.',{requests:3,duration:'32 сек',retries:3});persist();rerender();}
export function bindSync(){
  bindSyncHelp();
  document.querySelector('#sync-all')?.addEventListener('click',()=>runSync());
  document.querySelectorAll('[data-sync-scenario]').forEach(el=>el.onclick=()=>applyScenario(el.dataset.syncScenario));
  document.querySelector('#toggle-sync-pause')?.addEventListener('click',()=>{if(!admin())return;db.sync.config.paused=!db.sync.config.paused;persist();rerender();toast(db.sync.config.paused?'Автоматическая синхронизация приостановлена':'Синхронизация возобновлена');});
  document.querySelector('#reset-sync-config')?.addEventListener('click',()=>{rerender();toast('Несохранённые изменения отменены');});
  const form=document.querySelector('#sync-config-form');
  const updateBudget=()=>{if(!form)return;const rpm=form.elements.namedItem('rpm').value,concurrency=form.elements.namedItem('concurrency').value;const delay=Number(form.elements.namedItem('retryDelay').value);form.elements.namedItem('backoff').options[0].textContent=`Экспоненциальное · ${delay} → ${delay*2} → ${delay*4} сек`;document.querySelector('#sync-budget').innerHTML=`${safeIcon('activity')}<span>Не более <strong>${esc(rpm)}</strong> запросов/мин · до <strong>${esc(concurrency)}</strong> одновременно</span>`;};
  form?.addEventListener('input',updateBudget);
  form?.addEventListener('submit',e=>{e.preventDefault();if(!admin())return;const f=new FormData(form),cfg={...db.sync.config};for(const k of Object.keys(defaults)){if(k==='paused')continue;cfg[k]=k==='backoff'?f.get(k):Number(f.get(k));}const err=document.querySelector('#sync-form-error');const ranges={metaInterval:[1,1440],rollupInterval:[1,1440],rpm:[1,300],concurrency:[1,10],retries:[0,10],retryDelay:[1,300],timeout:[5,120],staleAfter:[5,1440]};if(Object.entries(ranges).some(([k,[min,max]])=>!Number.isInteger(cfg[k])||cfg[k]<min||cfg[k]>max)||!['exponential','fixed'].includes(cfg.backoff)){err.textContent='Проверьте параметры: значения должны быть целыми числами в допустимых пределах.';err.hidden=false;return;}if(cfg.concurrency>cfg.rpm){err.textContent='Число одновременных запросов не может превышать лимит запросов в минуту.';err.hidden=false;return;}db.sync.config=cfg;for(const k of ['meta','rollup'])db.sync[k].next=Date.now()+cfg[k==='meta'?'metaInterval':'rollupInterval']*60000;persist();rerender();toast('Параметры синхронизации сохранены');});
  document.querySelector('#sync-log-filter')?.addEventListener('change',e=>{document.querySelectorAll('[data-log-source]').forEach(el=>el.hidden=e.target.value!=='all'&&el.dataset.logSource!==e.target.value);});
  document.querySelectorAll('[data-sync-log]').forEach(el=>el.onclick=()=>{const log=db.sync.logs.find(x=>x.id===el.dataset.syncLog);if(!log)return;modal('Подробности синхронизации',`<div class="stack"><div class="row-between"><strong>${sourceNames[log.source]||esc(log.source)}</strong><span class="badge badge-${log.status==='success'?'green':'red'}">${log.status==='success'?'Успешно':'Ошибка'}</span></div><dl class="sync-times"><div><dt>Время</dt><dd>${dt(log.time)}</dd></div><div><dt>Запросов</dt><dd>${log.requests||0}</dd></div><div><dt>Длительность</dt><dd>${esc(durationLabel(log.duration))}</dd></div></dl><div class="notice ${log.status==='error'?'notice-amber':''}">${esc(log.message)}</div>${log.status==='error'?'<p class="muted small">Неудачная попытка не изменяет дату последней успешной загрузки.</p>':''}</div>`,`<button class="btn" data-modal-close>Закрыть</button>`);});
}
